import{_ as a,o,c as r,a0 as t}from"./chunks/framework.BQvjZmTX.js";const p=JSON.parse('{"title":"Command-Line Help for arca","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),c={name:"reference/cli.md"};function d(i,e,n,s,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="command-line-help-for-arca" tabindex="-1">Command-Line Help for <code>arca</code> <a class="header-anchor" href="#command-line-help-for-arca" aria-label="Permalink to &quot;Command-Line Help for `arca`&quot;">​</a></h1><p>This document contains the help content for the <code>arca</code> command-line program.</p><p><strong>Command Overview:</strong></p><ul><li><a href="#arca"><code>arca</code>↴</a></li><li><a href="#arca-init"><code>arca init</code>↴</a></li><li><a href="#arca-put"><code>arca put</code>↴</a></li><li><a href="#arca-get"><code>arca get</code>↴</a></li><li><a href="#arca-list"><code>arca list</code>↴</a></li><li><a href="#arca-rm"><code>arca rm</code>↴</a></li><li><a href="#arca-rotate"><code>arca rotate</code>↴</a></li><li><a href="#arca-run"><code>arca run</code>↴</a></li><li><a href="#arca-env"><code>arca env</code>↴</a></li><li><a href="#arca-check"><code>arca check</code>↴</a></li><li><a href="#arca-migrate"><code>arca migrate</code>↴</a></li><li><a href="#arca-deploy"><code>arca deploy</code>↴</a></li><li><a href="#arca-serve"><code>arca serve</code>↴</a></li><li><a href="#arca-ui"><code>arca ui</code>↴</a></li><li><a href="#arca-manifest"><code>arca manifest</code>↴</a></li><li><a href="#arca-schema"><code>arca schema</code>↴</a></li></ul><h2 id="arca" tabindex="-1"><code>arca</code> <a class="header-anchor" href="#arca" aria-label="Permalink to &quot;`arca`&quot;">​</a></h2><p>arca — secrets broker for agents: <code>arca://</code> refs, redaction, env-injection instead of plaintext.</p><p>Refs name logical secrets (<code>arca://billing/stripe</code>); <code>--env</code> picks the resolution context. <code>[secrets]</code> in arca.toml bounds what <code>run</code>/<code>env</code> may inject. <code>manifest</code>/<code>schema</code> describe the surface for machines; every verb honors <code>--json</code>.</p><p><strong>Usage:</strong> <code>arca [OPTIONS] &lt;COMMAND&gt;</code></p><h6 id="subcommands" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>init</code> — Bootstrap: store the age identity in the system keyring when a session secret store is reachable — importing an existing identity.txt rather than orphaning it — else the <code>~/.config/arca/identity.txt</code> keyfile (0600). Verifies the vault opens</li><li><code>put</code> — Store a secret. The value comes from stdin (<code>printf … | arca put arca://ns/name</code>) or a hidden terminal prompt — never args, which land in shell history and <code>/proc</code></li><li><code>get</code> — Print a secret&#39;s value to stdout — the escape hatch. Prefer <code>arca run</code> so values never enter agent context; guardrails can deny this op</li><li><code>list</code> — List the refs stored in the selected env — names only, never values</li><li><code>rm</code> — Remove a secret from the selected env</li><li><code>rotate</code> — Rotate a secret to a new value (stdin or hidden prompt, like <code>put</code>); bumps version + rotated_at</li><li><code>run</code> — Run a command with declared secrets injected as env vars</li><li><code>env</code> — Print <code>export VAR=&#39;…&#39;</code> lines for <code>eval &quot;$(arca env)&quot;</code> — the human path (<code>run</code> is the agent path). Values print to stdout: <code>--json</code> emits a <code>VAR → value</code> map</li><li><code>check</code> — Validate config + the declared surface: <code>[envs]</code> routes point at declared vaults, vaults decrypt, every <code>[secrets]</code> ref resolves in its routed env. Exit 1 on findings</li><li><code>migrate</code> — Rewrite stored records for a wire/config upgrade. Currently one transform: <code>--private-refs</code> re-keys every plaintext-named row in each env routed to a cf vault with <code>[vaults.*] private_refs = true</code> — ciphertext moves verbatim, old keys are deleted after the new rows land</li><li><code>deploy</code> — Push a stored secret to a write-only deploy target (<code>[deploy.NAME]</code> in arca.toml, e.g. a CF Secrets Store). The vault is the source of truth; the sink never gives the value back. With one configured target, <code>--target</code> may be omitted</li><li><code>serve</code> — Serve the Vault port over ndjson — one JSON request per stdin line, one response per stdout line, audit events on stderr unchanged. For orchestrators embedding arca (peregrin); with <code>[serve.pdp]</code> configured, a policy decision point is consulted before every vault-touching op. <code>{&quot;op&quot;:&quot;manifest&quot;}</code> on the wire describes the protocol</li><li><code>ui</code> — Interactive vault browser (requires the <code>tui</code> feature)</li><li><code>manifest</code> — Capabilities, JSON shapes, env vars, audit contract — agent self-discovery (always JSON)</li><li><code>schema</code> — JSON Schema for <code>arca.toml</code></li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--env &lt;ENV&gt;</code> — Env context — <code>dev</code>/<code>staging</code>/<code>prod</code>/custom. Overrides <code>ARCA_ENV</code>; default <code>dev</code></li><li><code>--config &lt;PATH&gt;</code> — Config file, overriding the search ($ARCA_CONFIG → ./arca.toml → ~/.config/arca/arca.toml)</li><li><code>--actor &lt;ACTOR&gt;</code> — Actor attribution for audit events (default $ARCA_ACTOR, else $USER)</li></ul><h2 id="arca-init" tabindex="-1"><code>arca init</code> <a class="header-anchor" href="#arca-init" aria-label="Permalink to &quot;`arca init`&quot;">​</a></h2><p>Bootstrap: store the age identity in the system keyring when a session secret store is reachable — importing an existing identity.txt rather than orphaning it — else the <code>~/.config/arca/identity.txt</code> keyfile (0600). Verifies the vault opens</p><p><strong>Usage:</strong> <code>arca init [OPTIONS]</code></p><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--with-file</code> — Force the identity keyfile even when a keyring is available — the headless/CI mode</li></ul><h2 id="arca-put" tabindex="-1"><code>arca put</code> <a class="header-anchor" href="#arca-put" aria-label="Permalink to &quot;`arca put`&quot;">​</a></h2><p>Store a secret. The value comes from stdin (<code>printf … | arca put arca://ns/name</code>) or a hidden terminal prompt — never args, which land in shell history and <code>/proc</code></p><p><strong>Usage:</strong> <code>arca put &lt;RREF&gt;</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;RREF&gt;</code> — <code>arca://</code> ref, e.g. arca://billing/stripe</li></ul><h2 id="arca-get" tabindex="-1"><code>arca get</code> <a class="header-anchor" href="#arca-get" aria-label="Permalink to &quot;`arca get`&quot;">​</a></h2><p>Print a secret&#39;s value to stdout — the escape hatch. Prefer <code>arca run</code> so values never enter agent context; guardrails can deny this op</p><p><strong>Usage:</strong> <code>arca get &lt;RREF&gt;</code></p><h6 id="arguments-1" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-1" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;RREF&gt;</code> — <code>arca://</code> ref</li></ul><h2 id="arca-list" tabindex="-1"><code>arca list</code> <a class="header-anchor" href="#arca-list" aria-label="Permalink to &quot;`arca list`&quot;">​</a></h2><p>List the refs stored in the selected env — names only, never values</p><p><strong>Usage:</strong> <code>arca list</code></p><h2 id="arca-rm" tabindex="-1"><code>arca rm</code> <a class="header-anchor" href="#arca-rm" aria-label="Permalink to &quot;`arca rm`&quot;">​</a></h2><p>Remove a secret from the selected env</p><p><strong>Usage:</strong> <code>arca rm &lt;RREF&gt;</code></p><h6 id="arguments-2" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-2" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;RREF&gt;</code> — <code>arca://</code> ref</li></ul><h2 id="arca-rotate" tabindex="-1"><code>arca rotate</code> <a class="header-anchor" href="#arca-rotate" aria-label="Permalink to &quot;`arca rotate`&quot;">​</a></h2><p>Rotate a secret to a new value (stdin or hidden prompt, like <code>put</code>); bumps version + rotated_at</p><p><strong>Usage:</strong> <code>arca rotate &lt;RREF&gt;</code></p><h6 id="arguments-3" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-3" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;RREF&gt;</code> — <code>arca://</code> ref</li></ul><h2 id="arca-run" tabindex="-1"><code>arca run</code> <a class="header-anchor" href="#arca-run" aria-label="Permalink to &quot;`arca run`&quot;">​</a></h2><p>Run a command with declared secrets injected as env vars.</p><p>Injection surface = <code>[secrets]</code> in arca.toml plus <code>-s VAR=arca://ref</code> ad-hoc pairs; nothing else is injectable. Two exec modes after <code>--</code>:</p><p><code>arca run -- &#39;pnpm test | tee log&#39;</code> — one string → <code>bash -c</code></p><p><code>arca run -- pnpm test --filter x</code> — argv → direct exec</p><p>argv mode needs no shell quoting — prefer it when the command has arguments. Exit code is the child&#39;s.</p><p><strong>Usage:</strong> <code>arca run [OPTIONS] -- &lt;CMD&gt;...</code></p><h6 id="arguments-4" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-4" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;CMD&gt;</code> — Command to run (after <code>--</code>). One arg → <code>bash -c</code>; several → <code>argv[0]</code> exec&#39;d directly with the rest</li></ul><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-s</code>, <code>--secret &lt;VAR=ARCA_REF&gt;</code> — Extra <code>VAR=arca://ref</code> pairs to inject (refused when <code>[guardrails] deny_adhoc</code> is set)</li></ul><h2 id="arca-env" tabindex="-1"><code>arca env</code> <a class="header-anchor" href="#arca-env" aria-label="Permalink to &quot;`arca env`&quot;">​</a></h2><p>Print <code>export VAR=&#39;…&#39;</code> lines for <code>eval &quot;$(arca env)&quot;</code> — the human path (<code>run</code> is the agent path). Values print to stdout: <code>--json</code> emits a <code>VAR → value</code> map</p><p><strong>Usage:</strong> <code>arca env [OPTIONS]</code></p><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-s</code>, <code>--secret &lt;VAR=ARCA_REF&gt;</code> — Extra <code>VAR=arca://ref</code> pairs to resolve</li></ul><h2 id="arca-check" tabindex="-1"><code>arca check</code> <a class="header-anchor" href="#arca-check" aria-label="Permalink to &quot;`arca check`&quot;">​</a></h2><p>Validate config + the declared surface: <code>[envs]</code> routes point at declared vaults, vaults decrypt, every <code>[secrets]</code> ref resolves in its routed env. Exit 1 on findings</p><p><strong>Usage:</strong> <code>arca check</code></p><h2 id="arca-migrate" tabindex="-1"><code>arca migrate</code> <a class="header-anchor" href="#arca-migrate" aria-label="Permalink to &quot;`arca migrate`&quot;">​</a></h2><p>Rewrite stored records for a wire/config upgrade. Currently one transform: <code>--private-refs</code> re-keys every plaintext-named row in each env routed to a cf vault with <code>[vaults.*] private_refs = true</code> — ciphertext moves verbatim, old keys are deleted after the new rows land</p><p><strong>Usage:</strong> <code>arca migrate [OPTIONS]</code></p><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--private-refs</code> — Re-key cf-vault rows under HMAC-derived storage keys, attaching the encrypted <code>name</code> blob (P-004)</li></ul><h2 id="arca-deploy" tabindex="-1"><code>arca deploy</code> <a class="header-anchor" href="#arca-deploy" aria-label="Permalink to &quot;`arca deploy`&quot;">​</a></h2><p>Push a stored secret to a write-only deploy target (<code>[deploy.NAME]</code> in arca.toml, e.g. a CF Secrets Store). The vault is the source of truth; the sink never gives the value back. With one configured target, <code>--target</code> may be omitted</p><p><strong>Usage:</strong> <code>arca deploy [OPTIONS] &lt;RREF&gt;</code></p><h6 id="arguments-5" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-5" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;RREF&gt;</code> — <code>arca://</code> ref to push</li></ul><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--target &lt;NAME&gt;</code> — Deploy target name (<code>[deploy.NAME]</code>); required when several are configured</li></ul><h2 id="arca-serve" tabindex="-1"><code>arca serve</code> <a class="header-anchor" href="#arca-serve" aria-label="Permalink to &quot;`arca serve`&quot;">​</a></h2><p>Serve the Vault port over ndjson — one JSON request per stdin line, one response per stdout line, audit events on stderr unchanged. For orchestrators embedding arca (peregrin); with <code>[serve.pdp]</code> configured, a policy decision point is consulted before every vault-touching op. <code>{&quot;op&quot;:&quot;manifest&quot;}</code> on the wire describes the protocol</p><p><strong>Usage:</strong> <code>arca serve</code></p><h2 id="arca-ui" tabindex="-1"><code>arca ui</code> <a class="header-anchor" href="#arca-ui" aria-label="Permalink to &quot;`arca ui`&quot;">​</a></h2><p>Interactive vault browser (requires the <code>tui</code> feature)</p><p><strong>Usage:</strong> <code>arca ui</code></p><h2 id="arca-manifest" tabindex="-1"><code>arca manifest</code> <a class="header-anchor" href="#arca-manifest" aria-label="Permalink to &quot;`arca manifest`&quot;">​</a></h2><p>Capabilities, JSON shapes, env vars, audit contract — agent self-discovery (always JSON)</p><p><strong>Usage:</strong> <code>arca manifest</code></p><h2 id="arca-schema" tabindex="-1"><code>arca schema</code> <a class="header-anchor" href="#arca-schema" aria-label="Permalink to &quot;`arca schema`&quot;">​</a></h2><p>JSON Schema for <code>arca.toml</code></p><p><strong>Usage:</strong> <code>arca schema</code></p><hr><p><small><i> This document was generated automatically by <a href="https://crates.io/crates/clap-markdown"><code>clap-markdown</code></a>. </i></small></p>',85)])])}const g=a(c,[["render",d]]);export{p as __pageData,g as default};
